test('lateFee with small amount and small overdue', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'MAGAZINE', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // MAGAZINE: 1250 cents, VAT 9%
  // Total: 1250 + 112.5 = 1362.5 → 1362 (banker's rounding) or 1363
  // Due date: depends on terms (default NET30)
  // Let's say 1 day overdue with amount 1363 cents
  // Fee = 1363 * 0.0004 * 1 = 0.5452 → 1 cent
  const result = lateFee(issued, '2024-03-16');

  assert.ok(result >= 0);
  assert.ok(result <= 1); // Very small fee for small amount
});

