test('vatSummary includes paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const paid = recordPayment(issued, { amount: 114950, date: '2024-01-20' }).value;
  const result = vatSummary([paid]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 95000);
  assert.equal(result[0].vat, 19950);
});

test('vatSummary with multiple VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'MAGAZINE', qty: 10 },
      { sku: 'TALK', qty: 1 },
    ],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const result = vatSummary([issued]);

  // Should have 3 entries, sorted by rate descending: 21, 9, 0
  assert.equal(result.length, 3);
  // DEV-HOUR: 10 * 9500 = 95000, vat = 95000 * 0.21 = 19950
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 95000);
  assert.equal(result[0].vat, 19950);
  // MAGAZINE: 10 * 1250 = 12500, vat = 12500 * 0.09 = 1125
  assert.equal(result[1].rate, 9);
  assert.equal(result[1].base, 12500);
  assert.equal(result[1].vat, 1125);
  // TALK: 1 * 35000 = 35000, vat = 0
  assert.equal(result[2].rate, 0);
  assert.equal(result[2].base, 35000);
  assert.equal(result[2].vat, 0);
});

test('vatSummary calculates base after discount', () => {
