    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const invoice2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-20',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const issued1 = issueInvoice(invoice1, []).value;
  const issued2 = issueInvoice(invoice2, ['INV-2024-0001']).value;
  const result = vatSummary([issued1, issued2]);

  // Both invoices have 21% VAT
  // Total: (10 * 9500) + (5 * 9500) = 142500 base
  // Total vat: 142500 * 0.21 = 29925
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 142500);
  assert.equal(result[0].vat, 29925);
