  // MAGAZINE: 10 * 1250 = 12500, vat = 12500 * 0.09 = 1125
  assert.equal(result[1].rate, 9);
  assert.equal(result[1].base, 12500);
  assert.equal(result[1].vat, 1125);
  // TALK: 1 * 35000 = 35000, vat = 0
  assert.equal(result[2].rate, 0);
  assert.equal(result[2].base, 35000);
  assert.equal(result[2].vat, 0);
});

