    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 20 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // DEV-HOUR: 10 * 9500 = 95000, discount 20% = 19000, base = 76000
  // Total after discount and VAT: 76000 + 15960 = 91960 cents
  // Due date: 2024-02-14, as of 2024-03-15 (30 days overdue)
  // Fee = 91960 * 0.0004 * 30 = 1103.52 → 1104 cents (banker's rounding)
  const result = lateFee(issued, '2024-03-15');

  assert.equal(result, 1104);
});

test('lateFee with tier discount', () => {
  // C-001 is gold tier with 5% discount
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // DEV-HOUR: 10 * 9500 = 95000, discount 5% = 4750, base = 90250
  // Total after discount and VAT: 90250 + 18952 = 109202 cents
  // Due date: 2024-02-14, as of 2024-03-15 (30 days overdue)
  // Fee = 109202 * 0.0004 * 30 = 1310.424 → 1310 cents (banker's rounding)
  const result = lateFee(issued, '2024-03-15');

  assert.equal(result, 1310);
});

test('lateFee on partially paid invoice with discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // DEV-HOUR: 10 * 9500 = 95000, discount 10% = 9500, base = 85500
  // Total: 85500 + 17955 = 103455 cents
  const partial = recordPayment(issued, { amount: 50000, date: '2024-01-20' }).value;
  // Balance due: 103455 - 50000 = 53455 cents
  // Due date: 2024-02-14, as of 2024-02-21 (7 days overdue)
  // Fee = 53455 * 0.0004 * 7 = 149.674 → 150 cents
  const result = lateFee(partial, '2024-02-21');

  assert.equal(result, 150);
});

