import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { lineTotal, lineDiscount, lineVAT } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Get a list of overdue invoices.
 * @param {Array<{ number?: string, customerId: string, status: string, dueDate?: string, lines: Array, payments?: Array }>} invoices
 * @param {string} asOf - date in YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter((inv) => (inv.status === 'issued' || inv.status === 'partially_paid'))
    .filter((inv) => inv.dueDate && inv.dueDate < asOf)
    .map((inv) => {
      const daysOverdue = daysBetween(inv.dueDate, asOf);
      const due = balanceDue(inv);

      return {
        number: inv.number || 'DRAFT',
        customerId: inv.customerId,
        dueDate: inv.dueDate,
        daysOverdue,
        due,
      };
    })
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

/**
 * Get a VAT summary by rate.
 * @param {Array<{ customerId: string, status: string, lines: Array }>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const vatMap = {};

  invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid')
    .forEach((invoice) => {
      invoice.lines.forEach((line) => {
        const rate = line.vatRate;
        const base = lineTotal(line) - lineDiscount(line);
        const vat = lineVAT(line);

        if (!vatMap[rate]) {
          vatMap[rate] = { rate, base: 0, vat: 0 };
        }

        vatMap[rate].base += base;
        vatMap[rate].vat += vat;
      });
    });

  return Object.values(vatMap).sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an invoice: 0.04% per day of the amount due.
 * @param {{ status: string, dueDate?: string, lines: Array, payments?: Array }} invoice
 * @param {string} asOf - date in YYYY-MM-DD format
 * @returns {number} late fee in cents, or 0 if not overdue
 */
export function lateFee(invoice, asOf) {
  if (!invoice.dueDate || invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const due = balanceDue(invoice);
  const fee = due * 0.0004 * daysOverdue;

  return roundCents(fee);
}
